import {roomsFor,resolveHeroPlan,HEROES,SKILLS} from './expedition-data.mjs';import {encounterEnemies} from './expedition-waves.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mechanismPreparationView(c,{actual=false,roomId=''}={}){const rows=roomsFor(c).filter(r=>(!roomId||r.id===roomId)&&encounterEnemies(r).some(u=>u.mechanism));if(!rows.length)return '';return `<section class="mechanism-preparation"><h3>机关拆解分工 · ${actual?'公会实际指令':'准备草稿'}</h3><p>普通攻击不能选中机关；拆解占该队员普通行动和3法力，队友负责清生物与保护。以下只核对逐房指令是否配置了拆解，不预测窗口、游标、存活、法力或成功率；有条目也不保证一定执行。</p>${rows.map(r=>{const actors=c.heroes.filter(h=>resolveHeroPlan(h,r.id).main.some(row=>SKILLS[row.skill]?.disarm));return `<article><b>${esc(r.name)}</b><p>公开机关：${encounterEnemies(r).filter(u=>u.mechanism).map(u=>esc(u.name)).join('、')}。</p><p class="${actors.length?'':'ready-diff'}">${actors.length?'配置拆解条目的队员：'+actors.map(h=>esc(HEROES.find(d=>d.id===h.id).name)).join('、'):'当前本房普通指令没有机巧拆解；普通攻击无法清除机关，请先核对伙伴职责和逐房覆盖。'}</p></article>`;}).join('')}</section>`;}
